 import '../session/session_tree.dart'
     show branchSummaryPrefix, compactionSummaryPrefix;
 import '../types.dart';
@@ -136,6 +137,7 @@ List<String> _replayUserTui(
     // byte-identical to [tuiMessageDividerBlock] in the live host.
     return ['', dim(tuiMessageDividerLayout(markerLine, width)), ''];
   }
+  if (isObligationsLedgerNotice(text)) return const [];
   if (needsSystemNoticeRewrite(text)) return renderSystemNoticeLines(text);
   // Chrome mode (issue #807): the SAME builder the live submit echo uses —
   // resume replay produces identical chrome (issue #807 AC4.5). Legacy
@@ -292,13 +294,16 @@ List<String> replayLines(
 }

 /// The user-message fast paths: summary markers and system-notice
-/// rewrites render verbatim, bypassing the prefix projection. Null =
-/// fall through to the regular prefix/body rendering.
+/// rewrites render verbatim, bypassing the prefix projection. The
+/// obligations-ledger tail skips the replay entirely (issue #2363 —
+/// engine chrome re-printed on every session open). Null = fall through
+/// to the regular prefix/body rendering.
 List<String>? _replayUserPrelude(Message message) {
   if (message case UserMessage(:final content)) {
     final text = _blocksText(content);
     final summaryLine = _summaryMarkerLine(text);
     if (summaryLine != null) return [summaryLine];
+    if (isObligationsLedgerNotice(text)) return const [];
     if (needsSystemNoticeRewrite(text)) return renderSystemNoticeLines(text);
   }
   return null;
diff --git a/lib/src/session/obligations_ledger.dart b/lib/src/session/obligations_ledger.dart
index 59ca7090a1..99ede5c21b 100644
--- a/lib/src/session/obligations_ledger.dart
+++ b/lib/src/session/obligations_ledger.dart
@@ -358,6 +358,22 @@ List<ObligationEntry> _closedTrailWithinBudget(
   return keptNewestFirst.reversed.toList();
 }

+/// The first line of the rendered obligations block (issue #1380 A1) —
+/// the notice's identity, shared by the renderer and [isObligationsLedgerNotice]
+/// so the spelling has ONE source of truth.
+const String obligationsLedgerNoticeHeading =
+    'obligations ledger (engine-maintained; verbatim quotes with their '
+    'source record — still owed unless marked done/superseded):';
+
+/// Whether [text] IS the engine-rendered obligations-ledger notice (the
+/// level-0 `<system-notice>` tail block the projection injects).
+/// Detection only: the resume replay skips it (issue #2363 — engine
+/// chrome is not transcript content and re-printing it on every session
+/// open is pure noise), while the model-visible context keeps it
+/// untouched (the #1380 level-0 invariant).
+bool isObligationsLedgerNotice(String text) =>
+    text.contains(obligationsLedgerNoticeHeading);
+
 /// The block the projection appends at level 0 (issue #1380 A1): every
 /// open obligation is visible — or explicitly counted — after any
 /// hide/compact/flatten depth.
@@ -374,9 +390,7 @@ String renderObligationsBlock(
   int maxChars = obligationsBlockBudgetChars,
 }) {
   if (ledger.isEmpty) return '';
-  const heading =
-      'obligations ledger (engine-maintained; verbatim quotes with their '
-      'source record — still owed unless marked done/superseded):';
+  const heading = obligationsLedgerNoticeHeading;
   final open = ledger.open;
   final stale = ledger.stale;
   final closed = ledger.closed;
